class Solution {
public:
    int minimumDifference(vector<int>& nums, int k) {
        int ans = INT_MAX;
        unordered_set<int> prev_ors;
        for (int x : nums) {
            unordered_set<int> cur_ors;
            cur_ors.insert(x);
            for (int v : prev_ors) {
                cur_ors.insert(x | v);
            }
            for (int v : cur_ors) {
                ans = min(ans, abs(v - k));
            }
            if (ans == 0) return 0;
            prev_ors = move(cur_ors);
        }
        return ans;
    }
};

class Solution {
    public int minimumDifference(int[] nums, int k) {
        int ans = Integer.MAX_VALUE;
        Set<Integer> prevOrs = new HashSet<>();
        for (int x : nums) {
            Set<Integer> curOrs = new HashSet<>();
            curOrs.add(x);
            for (int v : prevOrs) {
                curOrs.add(x | v);
            }
            for (int v : curOrs) {
                ans = Math.min(ans, Math.abs(v - k));
            }
            if (ans == 0) return 0;
            prevOrs = curOrs;
        }
        return ans;
    }
}

